
# Write the Boltz input YAML — this is exactly the format protacfold generates
from rdkit import Chem

raw_smiles = "OC=1C=C2C([C@H]([C@H](CC2)C3=CC=CC=C3)C4=CC=C(C=C4)N5CCC(CN6CCN(CC6)C=7C=C8C(=CC7)C(=O)N(C8)[C@@H]9C(=O)NC(=O)CC9)CC5)=CC1"
mol = Chem.MolFromSmiles(raw_smiles)
canonical = Chem.MolToSmiles(mol)

yaml_content = f"""version: 1
sequences:
- protein:
    id:
    - A
    sequence: SIKRSKKNSLALSLTADQMVSALLDAEPPILYSEYDPTRPFSEASMMGLLTNLADRELVHMINWAKRVPGFVDLTLHDQVHLLECAWLEILMIGLVWRSMEHPGKLLFAPNLLLDRNQGKCVEGMVEIFDMLLATSSRFRMMNLQGEEFVCLKSIILLNSGVYTFLSSTLKSLEEKDHIHRVLDKITDTLIHLMAKAGLTLQQQHQRLAQLLLILSHIRHMSNKGMEHLYSMKCKNVVPLSDLLLEMLDAHRLHAPTS
    msa: empty
- protein:
    id:
    - B
    sequence: 
    msa: empty
- ligand:
    id:
    - C
    smiles: {canonical}
"""

yaml_path = "/home/ubuntu/rayca-sessions/2d89c255-6bf5-4e5c-a4fb-99e4f253a979-1320c8c41b74/ARV471_ERalpha_CRBN_boltz_input.yaml"
with open(yaml_path, 'w') as f:
    f.write(yaml_content)

print("YAML written to:", yaml_path)
print("\nContent preview:")
print(yaml_content[:400])
